import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import crypto from 'node:crypto';
import { configSchema, type ConfigInput, CATEGORY_LABELS, STYLE_LABELS, WM_LABELS } from '../src/lib/schema';
import { fetchLimited, SCRIPT_HOSTS } from '../src/lib/fetch-limited';

const TAG_RE = /^[a-z0-9][a-z0-9-]{0,29}$/;
const SCRIPT_MAX_BYTES = 1024 * 1024;
const SCRIPT_TIMEOUT_MS = 10_000;
const PLACEHOLDER_SHA256 = '0'.repeat(64);

/**
 * Parses markdown generated by GitHub Issue Forms into a key-value record.
 * Empty optional fields (rendered as `_No response_`) become ''.
 */
export function parseIssueBody(markdown: string): Record<string, string> {
  const sections: Record<string, string> = {};
  const lines = markdown.split('\n');

  let currentHeading: string | null = null;
  let currentContent: string[] = [];

  for (const line of lines) {
    const headingMatch = line.match(/^###\s+(.+)$/);
    if (headingMatch) {
      if (currentHeading) {
        sections[currentHeading] = clean(currentContent);
      }
      currentHeading = headingMatch[1].trim();
      currentContent = [];
    } else if (currentHeading) {
      currentContent.push(line);
    }
  }

  if (currentHeading) {
    sections[currentHeading] = clean(currentContent);
  }

  return sections;
}

function clean(lines: string[]): string {
  const v = lines.join('\n').trim();
  return v === '_No response_' ? '' : v;
}

/** Reverse a `key -> label` map so a dropdown answer (label or key, any case) resolves to its schema key. */
function fromLabel<K extends string>(labels: Record<K, string>, answer: string): K | undefined {
  const a = answer.trim().toLowerCase();
  return (Object.keys(labels) as K[]).find((k) => k === a || labels[k].toLowerCase() === a);
}

/** Textareas rendered with `render: bash` arrive wrapped in a code fence: keep the non-empty command lines. */
export function parseCommands(raw: string): string[] {
  return raw
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('```'));
}

/** Checkbox fields render as `- [X] Arch` / `- [ ] Fedora`: keep checked labels only. Plain lists pass through. */
export function parseChecked(raw: string): string[] {
  const boxes = [...raw.matchAll(/^- \[([ xX])\] (.+)$/gm)];
  if (boxes.length === 0) return raw.split(/[\n,]/).map((s) => s.trim()).filter(Boolean);
  return boxes.filter((m) => m[1] !== ' ').map((m) => m[2].trim());
}

export async function convertIssueToConfig(
  issueAuthor: string,
  issueBody: string,
): Promise<{ config: ConfigInput; author: string; slug: string }> {
  const fields = parseIssueBody(issueBody);

  const name = fields['Project Name'] || fields['Configuration Name'] || '';
  const slug = (fields['Slug'] || '')
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9-]/g, '-');
  const summary = fields['Short Summary'] || '';
  const description = fields['Description'] || undefined;
  const license = fields['License (SPDX)'] || 'MIT';
  const wmAnswer = fields['Window Manager'] || '';
  const wm = fromLabel(WM_LABELS, wmAnswer) ?? (wmAnswer.toLowerCase() === 'awesome' ? 'awesome' : wmAnswer.toLowerCase());
  const category = fromLabel(CATEGORY_LABELS, fields['Desktop Part'] || '') ?? 'dotfiles';
  const themeStyle = fromLabel(STYLE_LABELS, fields['Theme Style'] || '') ?? 'other';
  const displayServerRaw = (fields['Display Server'] || 'wayland').trim().toLowerCase();
  const displayServer: 'wayland' | 'x11' | 'both' =
    displayServerRaw === 'both' || (displayServerRaw.includes('x11') && displayServerRaw.includes('wayland'))
      ? 'both'
      : displayServerRaw.includes('x11')
        ? 'x11'
        : 'wayland';

  const distrosRaw = fields['Distributions'] || 'arch';
  const distros = parseChecked(distrosRaw).map((s) => s.toLowerCase()) as any[];

  const tagsRaw = fields['Tags'] || '';
  const tags = [
    ...new Set(
      tagsRaw
        .split(/[\n, ]/)
        .map((s) => s.trim().toLowerCase().replace(/^#/, ''))
        .filter((s) => TAG_RE.test(s)),
    ),
  ].slice(0, 10);

  const screenshotsRaw = fields['Screenshots URLs'] || '';
  const screenshotUrls = screenshotsRaw
    .split('\n')
    .map((s) => s.trim())
    .filter((s) => s.startsWith('https://'));

  const screenshots = screenshotUrls.map((url, idx) => ({
    url,
    alt: `Screenshot ${idx + 1} of ${name}`,
    caption: `SHOT_${String(idx + 1).padStart(2, '0')}`,
  }));

  const sourceRepo = fields['Source Repository'] || '';
  const sourceRef = fields['Git Ref'] || '';

  const scriptUrl = fields['Install Script URL'] || undefined;
  const submittedSha256 = fields['Script SHA-256']?.trim() || undefined;

  const steps = (
    [
      ['deps', 'Install dependencies', fields['Install: Dependencies']],
      ['dotfiles', 'Deploy', fields['Install: Deploy']],
      ['reload', 'Reload', fields['Install: Reload']],
    ] as const
  )
    .map(([id, title, raw]) => ({ id, title, commands: parseCommands(raw || '') }))
    .filter((step) => step.commands.length > 0);

  const bar = fields['Status Bar'] || undefined;
  const terminal = fields['Terminal'] || undefined;
  const launcher = fields['Launcher'] || undefined;
  const theme = fields['Theme'] || undefined;
  const shell = fields['Shell'] || undefined;

  const config: ConfigInput = {
    $schema: '../../schema/config.schema.json',
    name,
    author: {
      name: issueAuthor,
      github: issueAuthor,
    },
    lang: 'en',
    summary,
    description: description || undefined,
    license,
    updatedAt: new Date().toISOString().split('T')[0],
    distros: distros.length > 0 ? distros : (['arch'] as any),
    category,
    wm: wm as any,
    themeStyle,
    displayServer: displayServer as any,
    tags,
    specs: {
      bar: bar || undefined,
      terminal: terminal || undefined,
      launcher: launcher || undefined,
      theme: theme || undefined,
      shell: shell || undefined,
    },
    screenshots,
    source: {
      repo: sourceRepo,
      ref: sourceRef,
      readme: 'README.md',
    },
    install: {
      script: scriptUrl ? { url: scriptUrl, sha256: PLACEHOLDER_SHA256, shell: 'bash' } : undefined,
      steps,
    },
    example: false,
  };

  if (scriptUrl) {
    const precheck = configSchema.safeParse(config);
    if (!precheck.success) {
      const msg = precheck.error.issues.map((i) => `[${i.path.join('.')}] ${i.message}`).join('\n');
      throw new Error(msg);
    }

    console.log(`Downloading script ${scriptUrl} to verify/calculate SHA-256...`);
    const res = await fetchLimited(scriptUrl, {
      maxBytes: SCRIPT_MAX_BYTES,
      timeoutMs: SCRIPT_TIMEOUT_MS,
      allowedHosts: SCRIPT_HOSTS,
    });
    if (res.status < 200 || res.status >= 300) {
      throw new Error(`Could not fetch script to compute SHA-256: HTTP ${res.status}`);
    }
    const computedSha256 = crypto.createHash('sha256').update(res.body).digest('hex');
    if (submittedSha256) {
      const expected = submittedSha256.toLowerCase();
      if (expected !== computedSha256) {
        throw new Error(`Script SHA-256 mismatch: expected ${expected}, got ${computedSha256}`);
      }
    }
    config.install.script = { url: scriptUrl, sha256: computedSha256, shell: 'bash' };
    console.log(`Verified SHA-256: ${computedSha256}`);
  }

  return { config, author: issueAuthor, slug };
}

function safeReadPath(filePath: string): string {
  const resolved = fs.realpathSync(filePath);
  const baseDir = fs.realpathSync(process.cwd());
  const tmpDir = fs.realpathSync(os.tmpdir());
  const isInside = (dir: string) => resolved === dir || resolved.startsWith(dir + path.sep);
  if (!isInside(baseDir) && !isInside(tmpDir)) {
    throw new Error(`path '${filePath}' is outside the allowed directory`);
  }
  return resolved;
}

function safeOutputDir(baseDir: string, author: string): string {
  const cleanAuthor = author.replace(/[^a-zA-Z0-9_-]/g, '');
  if (!cleanAuthor) {
    throw new Error(`Invalid author '${author}'`);
  }
  const resolvedBase = fs.realpathSync(baseDir);
  const target = path.resolve(resolvedBase, cleanAuthor);
  if (target !== resolvedBase && !target.startsWith(resolvedBase + path.sep)) {
    throw new Error(`path '${target}' is outside the allowed directory`);
  }
  return target;
}

function safeOutputFile(dir: string, slug: string): string {
  const cleanSlug = slug.replace(/[^a-z0-9_-]/g, '');
  if (!cleanSlug) {
    throw new Error(`Invalid slug '${slug}'`);
  }
  const resolvedDir = fs.realpathSync(dir);
  const target = path.resolve(resolvedDir, `${cleanSlug}.json`);
  if (target !== resolvedDir && !target.startsWith(resolvedDir + path.sep)) {
    throw new Error(`path '${target}' is outside the allowed directory`);
  }
  return target;
}

export interface IssueToConfigResult {
  status: 'ok' | 'error';
  mode: 'create' | 'update';
  path: string;
  errors: string[];
}

function writeResult(result: IssueToConfigResult): void {
  const resultPath = path.resolve(process.cwd(), 'issue-to-config-result.json');
  fs.writeFileSync(resultPath, JSON.stringify(result, null, 2), 'utf-8');
}

async function main() {
  const issueFile = process.argv[2];
  const issueAuthor = process.argv[3];

  let mode: 'create' | 'update' = 'create';
  let outRelPath = '';

  if (!issueFile || !issueAuthor) {
    const msg = 'Usage: tsx scripts/issue-to-config.ts <issue-body-file> <github-author>';
    console.error(msg);
    writeResult({ status: 'error', mode, path: outRelPath, errors: [msg] });
    process.exit(1);
  }

  try {
    const validFilePath = safeReadPath(issueFile);
    const body = fs.readFileSync(validFilePath, 'utf-8');
    const { config, author, slug } = await convertIssueToConfig(issueAuthor, body);

    const configsDir = path.resolve(process.cwd(), 'configs');
    const outDir = safeOutputDir(configsDir, author);
    const cleanSlug = slug.replace(/[^a-z0-9_-]/g, '');
    if (cleanSlug) {
      const candidateFile = path.resolve(outDir, `${cleanSlug}.json`);
      outRelPath = path.relative(process.cwd(), candidateFile).replace(/\\/g, '/');
      if (fs.existsSync(candidateFile)) {
        mode = 'update';
      }
    }

    const parsed = configSchema.safeParse(config);
    if (!parsed.success) {
      console.error('Validation error for generated config:');
      const errors = parsed.error.issues.map((issue) => `[${issue.path.join('.')}] ${issue.message}`);
      for (const line of errors) {
        console.error(`- ${line}`);
      }
      writeResult({ status: 'error', mode, path: outRelPath, errors });
      process.exit(1);
    }

    if (!fs.existsSync(outDir)) {
      fs.mkdirSync(outDir, { recursive: true });
    }

    const outFile = safeOutputFile(outDir, slug);
    outRelPath = path.relative(process.cwd(), outFile).replace(/\\/g, '/');
    mode = fs.existsSync(outFile) ? 'update' : 'create';

    fs.writeFileSync(outFile, JSON.stringify(parsed.data, null, 2), 'utf-8');
    writeResult({ status: 'ok', mode, path: outRelPath, errors: [] });
    console.log(`✓ Successfully ${mode === 'update' ? 'updated' : 'created'} configuration: ${outFile}`);
  } catch (err) {
    const rawMsg = err instanceof Error ? err.message : String(err);
    const errors = rawMsg.split('\n').map((s) => s.trim()).filter(Boolean);
    console.error(err);
    writeResult({
      status: 'error',
      mode,
      path: outRelPath,
      errors: errors.length > 0 ? errors : [rawMsg],
    });
    process.exit(1);
  }
}

if (process.argv[1] && process.argv[1].endsWith('issue-to-config.ts')) {
  main();
}
